(() => {
  const root=document.querySelector('#flight-results');if(!root)return;
  document.head.insertAdjacentHTML('beforeend','<style>.results-filter details{border-top:1px solid #e2e8f0;padding:13px 0}.results-filter details:first-of-type{border-top:0}.results-filter summary{font-weight:800;cursor:pointer;list-style:none}.results-filter summary:after{content:"⌄";float:right;color:#64748b}.results-filter label{display:grid;gap:5px;margin-top:10px;color:#475569;font-size:.82rem}.results-filter input[type=range]{accent-color:#f5c518;width:100%}.results-filter output{color:#1e3a8a;font-size:.76rem}.filter-options{display:grid;gap:7px;margin-top:10px;max-height:155px;overflow:auto}.filter-options label{display:flex;align-items:center;gap:7px;margin:0}</style>');
  const num=value=>{const match=String(value||'').match(/(\d+) jam(?: (\d+) menit)?|(\d+) menit/);return match?(Number(match[1]||0)*60+Number(match[2]||match[3]||0)):0};
  const hour=value=>{const match=String(value||'').match(/pukul (\d{1,2})\.(\d{2})/);return match?Number(match[1])+Number(match[2])/60:0};
  const controls=()=>({stops:document.querySelector('[name="filter-stops"]:checked')?.value||'all',baggage:document.querySelector('#filter-baggage')?.checked,departure:Number(document.querySelector('#filter-departure-range')?.value||0),arrival:Number(document.querySelector('#filter-arrival-range')?.value||23),duration:Number(document.querySelector('#filter-duration')?.value||2400),airlines:[...document.querySelectorAll('[data-airline-filter]:checked')].map(x=>x.value),layovers:[...document.querySelectorAll('[data-layover-filter]:checked')].map(x=>x.value)});
  const apply=()=>{const state=controls();root.querySelectorAll('.flight-result').forEach(card=>{const stops=card.querySelector('.flight-details')?.querySelectorAll('.itinerary-leg').length-1||0,main=card.children[1]?.textContent||'',details=card.querySelector('.flight-details')?.textContent||'',airline=card.querySelector('.airline-brand b')?.textContent||'',departure=hour(main),arrival=hour([...card.querySelectorAll('.itinerary-leg strong')].at(-1)?.textContent||''),duration=num(main);const visible=(state.stops==='all'||state.stops==='direct'&&stops===0||state.stops==='one-stop'&&stops<=1)&&(!state.baggage||/checked baggage|bagasi tercatat/i.test(details))&&departure>=state.departure&&arrival<=state.arrival&&duration<=state.duration&&(!state.airlines.length||state.airlines.includes(airline))&&(!state.layovers.length||state.layovers.some(name=>details.includes(name)));card.hidden=!visible});};
  const options=()=>{const airlines=[...new Set([...root.querySelectorAll('.airline-brand b')].map(x=>x.textContent).filter(Boolean))].sort((a,b)=>a.localeCompare(b)),layovers=[...new Set([...root.querySelectorAll('.itinerary-leg em')].map(x=>x.textContent.replace(/^Transit\s+/,'').split(' · ')[0]).filter(Boolean))].sort((a,b)=>a.localeCompare(b));const render=(target,items,attr)=>{const node=document.querySelector(target);if(!node||node.dataset.ready)return;node.dataset.ready='1';node.innerHTML=items.map(item=>`<label><input type="checkbox" ${attr} value="${item.replace(/"/g,'&quot;')}"> ${item}</label>`).join('')||'<small>Tidak ada pilihan</small>'};render('#filter-airlines',airlines,'data-airline-filter');render('#filter-layovers',layovers,'data-layover-filter')};
  const update=()=>{const d=document.querySelector('#filter-departure-range'),a=document.querySelector('#filter-arrival-range'),duration=document.querySelector('#filter-duration');document.querySelector('#filter-departure-time').textContent=`${String(d.value).padStart(2,'0')}:00 – 23:59`;document.querySelector('#filter-arrival-time').textContent=`00:00 – ${String(a.value).padStart(2,'0')}:59`;document.querySelector('#filter-duration-value').textContent=duration.value>=2400?'Semua durasi':`Maks. ${Math.floor(duration.value/60)} jam ${duration.value%60?`${duration.value%60} menit`:''}`;apply()};
  const relabel=()=>{const isRoundTrip=/pulang/i.test(document.querySelector('#result-route')?.textContent||'');if(isRoundTrip)root.querySelectorAll('[data-flight]').forEach(button=>{if(button.textContent.trim()==='Pilih pergi')button.textContent='Lihat opsi pulang'})};
  document.querySelector('.results-filter')?.addEventListener('input',update);new MutationObserver(()=>{document.querySelectorAll('.filter-options').forEach(x=>delete x.dataset.ready);options();update();relabel()}).observe(root,{childList:true,subtree:true});options();update();relabel();
})();
